let reportView='overview',dataFocusMonth='',categoryUI={category:'',count:6,end:'',compare:'previous'},expenseChangeMonth='',coverageMonth='',bankCatalogOffset=0,bankCatalogOpen=false,familyReviewSelectedMonth='',exploreUI={count:6,end:'',category:'',method:'',query:''},exploreShown=30,exploreFromOverview=false,trendThreshold=200,periodicDraft=null;
