function graphTransferSources(month,components){
 const transfer=components.reported.find(item=>item.key==='transfers');if(!transfer)return '';
 const source=monthlyExpenseFieldEvidence(plan,month,'transfers'),visible=source.records.slice(0,20);
 const canExclude=source.records.length>0&&source.records.length<=20&&source.records.every(row=>row.date&&row.amount>0)&&cents(source.unlinked)===0&&cents(source.imported)===cents(transfer.amount)&&plan.months[month]?.actual===true;
 const correction=canExclude?`<p class="help">אם כל ${source.records.length} התנועות הן בין חשבונות שלך, אפשר לסווג אותן כהעברה יוצאת פנימית: הכסף ממשיך להפחית עו״ש, אך אינו הוצאה או חסכון. תנועות המקור ויתרות הבנק יישמרו; הערכות לחודשים הבאים שהתבססו על הסכום הזה יתעדכנו. יש לבדוק גם שהזיכויים בחשבונות היעד לא סווגו כהכנסה.</p><button class="btn" type="button" data-graph-internal-transfers="${month}" ${demoPreview||plan.demo?'disabled':''}>סיווג ${money(transfer.amount)} כפנימי ושמירה</button>`:'';
 return `<details class="graph-field-sources" ${cents(transfer.amount)>1000000?'open':''}><summary>מקור ״העברות יוצאות״ · ${money(transfer.amount)}</summary>${visible.length?`<p class="help">תנועות בנק שקושרו לשדה: ${money(source.imported)}${source.records.length>visible.length?' · מוצגות 20 הגדולות מתוך '+source.records.length:''}.</p>${visible.map(row=>`<div class="graph-source-row"><span><bdi dir="auto">${esc(row.description||'העברה בנקאית')}</bdi>${row.beneficiary?`<small><bdi dir="auto">${esc(row.beneficiary)}</bdi></small>`:''}<small>${row.date?`<bdi dir="ltr">${esc(row.date)}</bdi>`:'תאריך מקור לא נשמר'}${row.account?' · '+esc(row.account):''}</small></span><strong>${money(row.amount,true)}</strong></div>`).join('')}`:'<p class="help">לא נמצאו תנועות בנק שיובאו ושויכו לשדה הזה בחודש הנבחר.</p>'}${cents(source.unlinked)!==0?`<p class="help graph-source-gap">פער בין הסכום החודשי לתנועות המקור המקושרות: ${money(source.unlinked,true)}. ייתכן שהוא הוזן ידנית או נשאר מהערכה קודמת; יש לבדוק לפני תיקון.</p>`:''}${correction}</details>`;
}
function openGraphExpenses(month,metric,opener){
 const {rows}=graphState(),row=rows.find(r=>r.month===month);if(!row||row.values[metric]===null||!Object.hasOwn(graphLabels,metric))return;
 document.getElementById('graph-expenses-dialog')?.remove();
 const plannedOnly=metric==='plannedExpense',reportedOnly=metric==='reportedSpending',result=graphTopExpenses(plan,month,{plannedOnly,reportedOnly}),total=row.values[metric==='reportedSpending'?'reportedSpending':plannedOnly?'plannedExpense':'spending'],gap=cents(total)-cents(result.explained),dialog=document.createElement('dialog');
 dialog.id='graph-expenses-dialog';dialog.className='graph-expenses-dialog';dialog.dir='rtl';dialog.setAttribute('aria-labelledby','graph-expenses-title');
 const components=monthlySpendingBreakdown(plan,month),componentGroups=reportedOnly?[['דיווח חודשי',components.reported]]:[['דיווח חודשי',components.reported],['תכנון וצ׳קים נפרדים',[...components.planned,...components.cheques]]];
 const breakdown=['reportedSpending','spending'].includes(metric)?`<details class="graph-breakdown" ${gap>1000000?'open':''}><summary>ממה מורכב הסכום?</summary>${componentGroups.map(([heading,items])=>items.length?`<h4>${heading}</h4>${items.map(item=>`<div class="graph-breakdown-row"><bdi dir="auto">${esc(item.label)}</bdi><strong>${money(item.amount,true)}</strong></div>`).join('')}`:'').join('')||'<p class="help">אין רכיבים זמינים.</p>'}${graphTransferSources(month,components)}</details>`:'';
 dialog.innerHTML=`<div class="section-heading"><div><h2 id="graph-expenses-title">${esc(monthLabel(month))}</h2><span class="muted">${row.estimated?'הערכה':plan.demo?'נתוני דוגמה':'דיווח בפועל'}${dirty&&!demoPreview?' · לא נשמר':''}</span></div><button type="button" class="btn" data-graph-close aria-label="סגירת פירוט ההוצאות">סגירה</button></div><div class="graph-expense-total"><span>${graphLabels[metric]}</span><strong>${money(row.values[metric])}</strong></div><section><h3>${plannedOnly?'הוצאות מתוכננות מובילות':'3 ההוצאות הגדולות'}</h3>${result.items.length?`<ol class="graph-expense-list">${result.items.map(e=>`<li><bdi dir="auto">${esc(e.name)}</bdi><strong>${money(e.amount)}</strong></li>`).join('')}</ol>`:'<p class="help">אין פירוט הוצאות זמין.</p>'}</section><section class="graph-top-categories"><h3>3 הקטגוריות המובילות</h3>${result.categories.length?result.categories.map(c=>`<button class="graph-category-row" type="button" data-graph-category="${esc(c.category)}" aria-label="${esc(c.category)}: ${esc(currency(c.amount))}. פתיחת המגמה"><span><i style="background:${categoryColor(c.category,plan)}" aria-hidden="true"></i><bdi dir="auto">${esc(c.category)}</bdi></span><strong>${money(c.amount)}</strong></button>`).join(''):'<p class="help">אין פירוט לפי קטגוריות.</p>'}</section><p class="help graph-popup-note">לפי הפירוט הזמין, לאחר זיכויים.${gap>0?' עוד '+currency(gap/100)+' ללא פירוט.':gap<0?' הפירוט גבוה מסך החודש; יש לבדוק התאמה.':''}</p>${breakdown}<details class="graph-popup-info"><summary>מה נכלל?</summary><p class="help">ההוצאות הגדולות בחודש אינן בהכרח הסיבה לעלייה מחודש קודם. הקטגוריות מסכמות את הפירוט בלבד; הוצאות מתוכננות ללא קטגוריה אינן נכללות בהן.</p></details>`;
 document.body.append(dialog);dialog.querySelector('[data-graph-close]').onclick=()=>dialog.close();dialog.addEventListener('click',async event=>{if(event.target.closest('[data-graph-internal-transfers]')){if(!billingCanEdit())return;try{const corrected=excludeInternalBankTransfers(plan,month);dialog.close();if(mutate(corrected,'ההעברות סווגו כפנימיות. שומר את התיקון…'))await save();}catch(error){notify(error.message);}return;}const category=event.target.closest('[data-graph-category]');if(category){dialog.close();reportView='categories';categoryUI.category=category.dataset.graphCategory;setDataContextMonth(month);render();scrollToSection('.app-page-title');return;}if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{dialog.remove();if(opener?.isConnected)opener.focus();},{once:true});dialog.showModal();
}
app.addEventListener('click',event=>{const point=event.target.closest('[data-graph-month]');if(point)openGraphExpenses(point.dataset.graphMonth,point.dataset.graphMetric,point);});
