 if(!review.available){const hasClosed=Object.keys(plan.months??{}).some(value=>value>=plan.startMonth&&value<asOf&&value!==monthlyPending&&plan.months[value]?.actual===true);return `<section class="panel data-overview"><h2>תמונת הנתונים</h2><p class="help">${hasClosed?'בחודש שנבחר אין דיווח בפועל של חודש סגור.':'אין עדיין חודש סגור עם דיווח בפועל.'} אפשר לבחור חודש אחר או לבדוק את מצב הנתונים.</p><button class="btn" type="button" data-overview-open="coverage">בדיקת מצב הנתונים</button></section>`;}
