function familyReviewView(){
 const months=Object.keys(plan.months??{}).filter(month=>month>=plan.startMonth&&month<todayMonth()&&month!==monthlyPending&&plan.months[month]?.actual).sort().reverse(),selected=months.includes(familyReviewSelectedMonth)?familyReviewSelectedMonth:months[0],readonly=demoPreview||plan.demo;
 if(!selected)return '<section class="panel family-review"><h2>סקירה משפחתית</h2><p class="help">כדי לסקור את ההוצאות דרוש חודש שהסתיים עם דיווח בפועל. אפשר להתחיל במרכז הדוחות.</p></section>';
 const result=familyReviewMonth(plan,selected,todayMonth(),monthlyPending),labels={worthwhile:'היה שווה',review:'לבדוק',reduce:'לצמצם בפעם הבאה',unmarked:'טרם סומן'},coverageLabel={matched:'הפירוט תואם לסך החודש',partial:'הפירוט חלקי',over:'הפירוט גבוה מסך החודש',missing:'אין פירוט'};
 const statusButton=(row,status)=>`<button class="btn ${row.status===status?'primary':''}" type="button" data-family-status="${status}" data-family-category="${esc(row.category)}" data-family-month="${selected}" aria-pressed="${row.status===status}" ${readonly?'disabled':''}>${labels[status]}</button>`;
 return `<section class="panel family-review"><div class="section-heading"><h2>סקירה משפחתית</h2><span class="muted">בחירה שלכם · לפי חודש החיוב</span></div>${select('חודש סגור','family-review-month',months.map(month=>[month,monthLabel(month)]),selected)}<p class="help">סך ההוצאות שדווחו בחודש: ${money(result.total)} · ${coverageLabel[result.coverage.detail.status]}. ${result.coverage.bankFiles||result.coverage.cardFiles?'נקלטו קובצי מקור לחלק מהדיווחים; יש לבדוק את כיסוי כל המקורות.':'הסכומים עשויים להתבסס על דיווח ידני; אין כאן אימות של כל המקורות.'}</p><div class="family-totals">${Object.entries(labels).map(([status,label])=>`<div><span>${label}</span><strong>${money(result.statusCents[status]/100,true)}</strong></div>`).join('')}</div><p class="help">הסכומים שלעיל הם נטו מתוך פירוט ההוצאות שסומן או טרם סומן, אחרי זיכויים. הם אינם שיעור מתוך כלל התקציב.</p>${result.remainderCents!==0?`<p class="family-gap" role="status">${result.remainderCents>0?'ללא פירוט או התאמה':'הפירוט גבוה מסך ההוצאות'}: ${money(Math.abs(result.remainderCents)/100)}. אין לייחס את הפער לאחת הבחירות.</p>`:''}<div class="family-rows">${result.categories.map(row=>`<article class="family-row"><div class="family-row-heading"><span><i style="background:${categoryColor(row.category,plan)}" aria-hidden="true"></i><bdi dir="auto">${esc(row.category)}</bdi></span><strong>${money(row.amount,true)}</strong></div><div class="family-choices" role="group" aria-label="בחירה עבור ${esc(row.category)}">${statusButton(row,'worthwhile')}${statusButton(row,'review')}${statusButton(row,'reduce')}${row.status?`<button class="btn" type="button" data-family-status="reset" data-family-category="${esc(row.category)}" data-family-month="${selected}" ${readonly?'disabled':''}>ניקוי סימון</button>`:''}</div><button class="btn family-explore" type="button" data-family-explore="${esc(row.category)}" data-family-month="${selected}">לרשומות</button></article>`).join('')||'<p class="help">אין פירוט הוצאות שסולק בחודש הזה. הסכום החודשי נשאר ללא שיוך לבחירה משפחתית.</p>'}</div>${result.unreviewed.length?`<details class="family-stale"><summary>${result.unreviewed.length} סימונים לקטגוריות שכבר אינן בפירוט החודש</summary>${result.unreviewed.map(row=>`<div><bdi dir="auto">${esc(row.category)}</bdi><button class="btn" type="button" data-family-status="reset" data-family-category="${esc(row.category)}" data-family-month="${selected}" ${readonly?'disabled':''}>מחיקת סימון ישן</button></div>`).join('')}</details>`:''}<p class="help">הבחירה חלה על סך הקטגוריה בחודש הזה, לא על כל קנייה בנפרד. הוצאה גבוהה יכולה להיות חשובה למשפחה; אין דירוג אוטומטי של מה ״מוצדק״. סימונים יישמרו בתקציב רק אחרי לחיצה על ״שמור שינויים״.</p>${typeof familyPurchaseReviewView==='function'?familyPurchaseReviewView(selected):''}<button class="btn" type="button" data-report-view="coverage">בדיקת מצב הנתונים לחודש</button></section>`;
}
