function dataCoverageView(){
 const months=[...new Set([dataContextMonth(),todayMonth(),...Object.keys(plan.months??{}),...(plan.bankImport?.batches??[]).flatMap(batch=>(batch.months??[]).map(row=>row.month)),...(plan.cardBilling?.reports??[]).map(report=>report.dueDate.slice(0,7))])].filter(month=>month>=plan.startMonth&&(month<=todayMonth()||month===dataFocusMonth)).sort().reverse();
 if(!months.length)return '<section class="panel"><h2>מצב הנתונים</h2><p class="help">עדיין אין חודש שהגיע בתקופת התקציב.</p></section>';
 const month=months.includes(coverageMonth)?coverageMonth:dataContextMonth(),coverage=monthlyDataCoverage(plan,month,todayMonth(),monthlyPending),bankAudit=bankMovementAudit(plan,month);
 const rows=(entries,labels,empty)=>entries.length?entries.map(entry=>`<div class="coverage-source"><bdi dir="auto">${esc(entry.label)}</bdi><span data-status="${entry.status}">${esc(labels[entry.status])}</span></div>`).join(''):`<p class="help">${empty}</p>`;
 const bankAuditRow=(label,key)=>{const group=bankAudit.groups[key];return group.count?`<div class="coverage-source coverage-bank-row"><span>${label} · <bdi dir="ltr">${group.count}</bdi> תנועות</span><strong>יציאות ${money(group.debitCents/100)}${group.creditCents?' · כניסות '+money(group.creditCents/100):''}</strong></div>`:'';};
 const primaryBankRows=bankAuditRow('הוצאה ישירה אפשרית · לקטלוג','direct')+bankAuditRow('העברות שדורשות בירור יעד','transfers')+bankAuditRow('סילוק כרטיס · אינו רכישה נוספת','cards');
 const otherBankRows=bankAuditRow('הפקדות לחיסכון ולהשקעה','saving')+bankAuditRow('החזרי הלוואות','loans')+bankAuditRow('הכנסות','income')+bankAuditRow('תנועות שהוחרגו','excluded');
 const bankAuditHtml=bankAudit.totalCount?`<h3>מיפוי תנועות הבנק</h3><p class="help">חלוקה לפי השיוך הנוכחי של תנועת הבנק. הסכומים להלן הם תנועות מקור בלבד ואינם נוספים לסך ההוצאות.</p>${primaryBankRows||'<p class="help">אין הוצאה ישירה, העברה או חיוב כרטיס בדוח של חודש זה.</p>'}${otherBankRows?`<details class="coverage-bank-more"><summary>תנועות נוספות</summary>${otherBankRows}</details>`:''}${bankAudit.sourceMissing?`<p class="help">ל־${bankAudit.sourceMissing} תנועות יש סיכום ישן ללא שדות המקור; יש לעיין בדוח לפני שיוך קטגוריה.</p>`:''}<p class="help">העברה בין החשבונות שלכם אינה הוצאה של משק הבית. לפני שיוך קטגוריה נצטרך גם לזהות התאמה לפירוט קיים, כדי לא לספור אותה פעמיים.</p>`:'<p class="help">אין תנועות בנק מיובאות בחודש זה שאפשר לבדוק לקטלוג.</p>';
 const candidates=(plan.bankImport?.entries??[]).filter(entry=>entry.month===month&&entry.source&&['variable','checks'].includes(entry.field)&&entry.cents<0).sort((a,b)=>(b.source.date??'').localeCompare(a.source.date??'')||a.key.localeCompare(b.key));
 const bankCategories=bankCategoryCoverage(plan,month);
 const offset=Math.min(bankCatalogOffset,Math.max(0,Math.ceil(candidates.length/20)-1)*20),page=candidates.slice(offset,offset+20),categories=knownCategories();
 const catalogHtml=candidates.length?`<details class="coverage-bank-more" data-bank-catalog ${bankCatalogOpen?'open':''}><summary>שיוך קטגוריות לתשלומי בנק · ${candidates.filter(entry=>entry.bankCategoryId).length}/${candidates.length} סווגו</summary><p class="help">סווגו ${money(bankCategories.categorizedCents/100)} מתוך ${money(bankCategories.totalCents/100)} בתשלומי בנק ישירים; ${money(bankCategories.unclassifiedCents/100)} עדיין ללא קטגוריה. סכומים אלה נפרדים מסך ההוצאות ומפירוט הכרטיסים.</p><p class="help">רק תשלומים ישירים עם פרטי מקור מוצגים. בחרו קטגוריה רק אם זו הוצאה לצד שלישי. השיוך מתאר את תנועת הבנק; הוא אינו מוסיף סכום להוצאות. אפשר לאשר בנפרד התאמה לפירוט ישיר קיים לאחר בדיקת המקורות; האישור אינו משנה סכומים. השינוי נשמר רק בלחיצה על ״שמור שינויים״.</p>${page.map(entry=>{const label=plan.categoryRegistry?.entries?.find(category=>category.id===entry.bankCategoryId)?.label??'',name=[entry.source.description,entry.source.beneficiary].filter(Boolean).join(' · ')||'תשלום בנק',matches=possibleBankDetailMatches(plan,entry);return `<div class="coverage-source coverage-bank-row"><span><bdi dir="auto">${esc(name)}</bdi><small> · <bdi dir="ltr">${esc(entry.source.date)}</bdi> · ${money(-entry.cents/100)}</small>${matches.length?`<small class="bank-match-hint">ייתכן שכבר מופיע בפירוט: ${matches.map(detail=>`<bdi dir="auto">${esc(detail.name)}</bdi> · <bdi dir="ltr">${esc(detail.date)}</bdi>`).join(' / ')}. התאמה לפי סכום ותאריך בלבד; יש לבדוק ידנית.</small>`:''}${bankDetailLinkControls(entry,matches)}</span><label class="field">קטגוריה<select data-bank-category="${esc(entry.key)}" ${demoPreview||plan.demo?'disabled':''}><option value="">ללא שיוך</option>${categories.map(category=>`<option value="${esc(category)}" ${category===label?'selected':''}>${esc(category)}</option>`).join('')}</select></label></div>`;}).join('')}<div class="actions"><button class="btn" type="button" data-bank-catalog-page="previous" ${offset===0?'disabled':''}>הקודמות</button><span>${offset+1}–${Math.min(offset+20,candidates.length)} מתוך ${candidates.length}</span><button class="btn" type="button" data-bank-catalog-page="next" ${offset+20>=candidates.length?'disabled':''}>הבאות</button></div></details>`:'';
 return `<section class="panel data-coverage"><div class="section-heading"><h2>מצב הנתונים</h2></div>${select('חודש לבדיקה','coverage-month',months.map(value=>[value,monthLabel(value)]),month)}<p class="help">${coverage.closed?'החודש הסתיים':'החודש עדיין פתוח'} · ${coverage.actual?'יש דיווח בפועל':'אין דיווח בפועל'}${month===monthlyPending?' · קיימות עריכות שטרם נשמרו':''}</p><div class="coverage-summary"><span>דוחות בנק לחודש מלא <strong>${coverage.accounts.length?`<bdi dir="ltr">${coverage.bankFiles}/${coverage.accounts.length}</bdi>`:'אין חשבונות'}</strong></span><span>דוחות כרטיס מקובץ <strong><bdi dir="ltr">${coverage.cardFiles}/${coverage.cards.length}</bdi></strong></span></div><h3>חשבונות בנק</h3>${rows(coverage.accounts,bankEvidenceLabels,'לא הוגדר חשבון בנק בתקציב.')}<h3>כרטיסי אשראי</h3>${rows(coverage.cards,cardEvidenceLabels,'אין כרטיסים פעילים בחודש זה.')}${bankReconciliationView(month)}${periodReviewControls(month)}${plan.bankDetailRejections?.length?`<p class="help">${plan.bankDetailRejections.length} מועמדויות התאמה נדחו. <button class="btn" data-bank-rejections-reset>איפוס הדחיות לבדיקה מחדש</button></p>`:''}${bankAuditHtml}${catalogHtml}${staleBankDetailLinksView()}<h3>פירוט הוצאות</h3><p class="coverage-detail" data-status="${coverage.detail.status}">${esc(detailEvidenceLabels[coverage.detail.status])}${coverage.detail.remainderCents!==null&&coverage.detail.remainderCents>0?' · '+money(coverage.detail.remainderCents/100)+' ללא פירוט':''}</p><p class="help">המצב מציין אילו מקורות קיימים באפליקציה. דוח שנקלט אינו מוכיח שכל תנועה אפשרית הופיעה בו. דיווח ידני יכול להיות נכון, אך אינו מחליף קובץ מקור לצורך בדיקת כיסוי.</p><button class="btn" type="button" data-action="report-inbox">פתיחת מרכז הדוחות</button></section>`;
}
app.addEventListener('change',event=>{if(event.target.name==='coverage-month'){bankCatalogOffset=0;bankCatalogOpen=false;setDataContextMonth(event.target.value);render();return;}const input=event.target.closest('[data-bank-category]');if(!input||demoPreview||plan.demo)return;bankCatalogOpen=true;try{mutate(assignBankMovementCategory(plan,input.dataset.bankCategory,input.value),'קטגוריית תנועת הבנק עודכנה בטיוטה. יש לשמור את התקציב.');}catch(error){notify(error.message);render();}});
app.addEventListener('click',event=>{const button=event.target.closest('[data-bank-catalog-page]');if(!button)return;bankCatalogOpen=true;bankCatalogOffset=Math.max(0,bankCatalogOffset+(button.dataset.bankCatalogPage==='next'?20:-20));render();});
function expenseChangesView(){
 const months=Object.keys(plan.months??{}).filter(month=>plan.months[month]?.actual&&month<=todayMonth()&&month>=plan.startMonth).sort().reverse();
 if(!months.length)return '<section class="panel"><h2>מה השתנה בהוצאות?</h2><p class="help">כדי להשוות דרושים שני דיווחים בפועל בחודשים רצופים.</p></section>';
 const month=expenseChangeMonth||dataContextMonth(),choices=[...new Set([month,...months])].sort().reverse();
 let result;try{result=expenseChange(plan,{month,asOf:todayMonth(),excludeMonth:monthlyPending});}catch(error){return `<section class="panel error-box">${esc(error.message)}</section>`;}
 return `<section class="panel expense-changes"><div class="section-heading"><h2>מה השתנה בהוצאות?</h2></div>${select('חודש להשוואה','expense-change-month',choices.map(value=>[value,monthLabel(value)]),month)}${!result.available?`<p class="help">${esc(result.reason)}</p>`:`<p class="help">${esc(monthLabel(result.previousMonth))} לעומת ${esc(monthLabel(month))} · לפי חודש החיוב · ₪</p><div class="expense-change-totals"><span>בחודש הקודם <strong>${money(result.previousTotal)}</strong></span><span>בחודש הנבחר <strong>${money(result.total)}</strong></span><span>שינוי <strong>${money(result.change,true)}</strong></span></div><h3>פירוק השינוי</h3><div class="expense-change-rows">${result.parts.filter(part=>part.change!==0).map(part=>`<div class="expense-change-row"><span>${part.remainder?'':`<i style="background:${categoryColor(part.category,plan)}" aria-hidden="true"></i>`}<bdi dir="auto">${esc(part.category)}</bdi></span><strong>${money(part.change,true)}</strong></div>`).join('')||'<p class="help">אין שינוי בסכומים בין החודשים.</p>'}</div><p class="help">סכום השינויים בקטגוריות ובשארית שווה לשינוי הכולל. ״ללא פירוט או התאמה״ כולל הוצאות שלא שויכו לקטגוריה, ותיקוני התאמה כאשר הפירוט גבוה מהסך החודשי.</p><p class="help">${result.partialMonth?'החודש הנבחר טרם הסתיים; ההשוואה עשויה להשתנות. ':''}${result.detailMatched?'הפירוט תואם לסכומי החודש בשני החודשים.':'הפירוט אינו מלא או אינו תואם בשני החודשים; אין להסיק מהקטגוריות לבדן על כלל השינוי.'}${dirty&&!demoPreview?' השינויים כוללים עריכות שעדיין לא נשמרו.':''}</p>${merchantChangeView(month)}`}</section>`;
}
app.addEventListener('change',event=>{if(event.target.name==='expense-change-month'){setDataContextMonth(event.target.value);render();}});
function categoryChangeLabel(row){
 if(row.change===null)return 'אין חודש להשוואה';
 if(row.percent!==null)return row.percent===0?'ללא שינוי':`${row.percent>0?'עלייה':'ירידה'} ${Math.abs(row.percent)}%`;
 if(row.baselineAmount===0&&row.amount>0)return 'הוצאה חדשה';
 return 'שינוי של '+currency(row.change);
}
function sustainedTrendCard(end){
 const closedEnd=end>=todayMonth()?monthAt(todayMonth(),-1):end,result=sustainedExpenseTrend(plan,{endMonth:closedEnd,asOf:todayMonth(),category:categoryUI.category,minimumChange:trendThreshold,excludeMonth:monthlyPending});
 const basis=categoryUI.category?'פירוט קטגוריה שתואם את ההוצאות בכל חודש':'סך ההוצאות שדווחו בפועל';
 const verdict=result.available?(result.direction==='increase'?'עלייה רצופה':result.direction==='decrease'?'ירידה רצופה':'לא זוהתה מגמה רצופה מעל הסף'):'';
 return `<section class="sustained-trend"><div class="section-heading"><h3>מגמה בשלושה חודשים סגורים</h3><span class="muted">עד ${esc(monthLabel(closedEnd))}</span></div><label class="field">סף שינוי כולל · ₪<input name="trend-threshold" type="number" min="0" max="1000000" step="0.01" inputmode="decimal" value="${trendThreshold}"></label>${result.available?`<div class="trend-months">${result.months.map(row=>`<span>${esc(monthLabel(row.month))}<strong>${money(row.amount)}</strong></span>`).join('')}</div><p class="trend-verdict ${result.direction}"><strong>${verdict}</strong>${result.direction==='none'?'':` · שינוי של ${money(Math.abs(result.change))}`}</p>${result.direction==='increase'?`<button class="btn" type="button" data-insight-open data-category="${esc(categoryUI.category)}" data-reduction="${result.change}">בדיקת צמצום אפשרי בתרחיש</button>`:''}`:`<p class="help">${esc(result.reason)}</p>`}<p class="help">${basis}. נדרשת עלייה או ירידה בכל מעבר בין חודשים, וגם שינוי כולל מעל הסף. הסכומים הם נטו אחרי זיכויים ולפי חודש החיוב; מגמה אינה קובעת אם הוצאה הייתה מוצדקת.${plan.demo?' אלה נתוני דוגמה.':''}</p></section>`;
}
function categoryDataView(){
 const end=categoryUI.end||todayMonth(),series=categoryTrend(plan,{...categoryUI,endMonth:end,asOf:todayMonth(),excludeMonth:monthlyPending}),categories=knownCategories(),color=categoryColor(categoryUI.category||'אחר',plan),max=Math.max(1,...series.filter(r=>r.hasDetails).map(r=>Math.abs(r.amount))),hasRefund=series.some(r=>r.hasDetails&&r.amount<0),baseline=categoryUI.compare==='next'?'החודש הבא':'החודש הקודם';
 const available=series.filter(r=>r.hasDetails),sum=available.reduce((n,r)=>n+cents(r.amount),0)/100;
 return `<section class="panel category-data-panel"><div class="section-heading"><h2>קטגוריות לאורך זמן</h2><i class="data-category-dot" style="background:${color}" aria-hidden="true"></i></div><div class="graph-controls">${select('קטגוריה','data-category',[['','כל הקטגוריות'],...categories.map(c=>[c,c])],categoryUI.category)}${select('טווח','data-count',[[6,'6 חודשים'],[12,'12 חודשים'],[24,'24 חודשים']],categoryUI.count)}<label class="field">עד לחודש<input name="data-end" type="month" min="${plan.startMonth}" max="2099-12" value="${end}"></label>${select('שינוי באחוזים לעומת','data-compare',[['previous','החודש הקודם'],['next','החודש הבא'],['year','אותו חודש בשנה הקודמת']],categoryUI.compare)}</div><div class="category-data-summary"><span>סך הפירוט בטווח <strong>${money(sum)}</strong></span><span><bdi>${available.length}</bdi> מתוך <bdi>${series.length}</bdi> חודשים עם פירוט</span></div>${sustainedTrendCard(end)}<div class="category-data-scroll" tabindex="0" role="region" aria-label="עמודות הוצאות חודשיות בשקלים; הזמן מתקדם מימין לשמאל"><ol class="category-data-bars" style="--category-color:${color};--positive-space:${hasRefund?100:140}px;--refund-space:${hasRefund?100:0}px">${series.map(row=>{const positive=row.hasDetails&&row.amount>=0,height=Math.abs(row.amount)/max*(hasRefund?100:140),label=categoryChangeLabel(row);return `<li class="category-data-column"><strong>${row.hasDetails?money(row.amount):'—'}</strong><div class="category-data-plot" aria-hidden="true"><div class="category-data-positive">${positive?`<span style="height:${Math.max(row.amount>0?3:0,height)}px"></span>`:''}</div><div class="category-data-negative">${row.hasDetails&&row.amount<0?`<span style="height:${Math.max(3,height)}px"></span>`:''}</div>${!row.hasDetails?'<span class="category-no-data">אין פירוט</span>':''}</div><span>${monthLabel(row.month)}</span><span class="category-change ${row.change>0?'increase':row.change<0?'decrease':''}" aria-label="${esc(label+' לעומת '+monthLabel(row.baselineMonth))}">${esc(label)}</span><small>${row.hasDetails?(row.month>todayMonth()?'חיוב עתידי':row.change!==null&&row.baselineMonth>todayMonth()?'מול חיוב עתידי':row.comparisonComplete?'פירוט תואם':plan.demo?'דוגמה':'פירוט חלקי'):''}</small></li>`;}).join('')}</ol></div><p class="help">כל עמודה מציגה את הפירוט נטו בחודש החיוב, אחרי זיכויים. האחוזים הם לעומת ${baseline}; כשסכום ההשוואה הוא אפס או זיכוי לא מוצג אחוז מטעה. חודשים ללא פירוט אינם אפס.</p><p class="help">פירוט חלקי או חודש שעדיין לא הסתיים עשויים להשפיע על ההשוואה. הוצאות ללא קטגוריה ותכנון ללא פירוט אינם נכללים; חיוב עתידי אינו הוצאה שכבר בוצעה.</p></section>`;
}
app.addEventListener('click',event=>{const button=event.target.closest('[data-report-view]');if(!button)return;if((hasPeriodicDraft()||typeof hasInsightDraft==='function'&&hasInsightDraft())&&button.dataset.reportView!==reportView){notify('יש לאשר או לבטל את העריכה לפני מעבר.');return;}if(hasDataContext(button.dataset.reportView))setDataContextMonth(dataContextMonth());if(button.dataset.reportView==='explore')exploreFromOverview=false;reportView=button.dataset.reportView;render();scrollToSection('.app-page-title');});
app.addEventListener('change',event=>{const target=event.target;if(target.name!=='trend-threshold')return;if(!target.checkValidity()){target.reportValidity();return;}trendThreshold=Number(target.value);try{localStorage.setItem('monthly-flow-trend-threshold/'+accountId+'/'+activeBudget,String(trendThreshold));}catch{notify('הסף עודכן, אך לא ניתן לזכור אותו במכשיר.');}render();});
app.addEventListener('change',event=>{const target=event.target;if(!['data-category','data-count','data-end','data-compare'].includes(target.name))return;if(!target.checkValidity()){target.reportValidity();return;}const next={...categoryUI,[target.name.slice(5)]:target.name==='data-count'?Number(target.value):target.value};try{categoryTrend(plan,{...next,endMonth:next.end||todayMonth(),asOf:todayMonth()});categoryUI=next;if(target.name==='data-end')setDataContextMonth(next.end);render();}catch(error){notify(error.message);}});

app.addEventListener('toggle',event=>{if(event.target.matches?.('[data-bank-catalog]'))bankCatalogOpen=event.target.open;},true);

function expenseAnomalyView(){
 const result=expenseAnomalies(plan,{asOf:todayMonth(),excludeMonth:monthlyPending,minimum:trendThreshold});
 if(!result.available||!result.items.length)return '';
 const row=result.items[0];
 if(row.decision)return `<details class="panel"><summary>תובנה שסומנה כ${row.decision==='expected'?'מוכרת וצפויה':'נדחתה'}</summary><button class="btn" data-expense-insight="reset" data-insight-key="${esc(row.key)}">הצגת התובנה מחדש</button></details>`;
 return `<section class="panel"><h3>עלייה מול שלושת חודשי הבסיס</h3><p>ההוצאות שדווחו ב־${esc(monthLabel(row.month))} הן ${money(row.actualCents/100)}, ${money(row.differenceCents/100)} מעל החציון ${money(row.baselineCents/100)}.</p><p class="help">לפי חודש החיוב, כלל התקציב. נדרשת עלייה של לפחות20% וגם ${money(trendThreshold)}. השוואת דיווחים חודשיים אינה אימות של כל מקורות הנתונים ואינה קובעת שההוצאה מיותרת. עדכניות: ${esc(monthLabel(row.month))}.</p><button class="btn" data-report-view="changes">בדיקת השינוי והמקורות</button><button class="btn" data-expense-insight="dismissed" data-insight-key="${esc(row.key)}" ${demoPreview||plan.demo?'disabled':''}>דחיית התובנה</button><button class="btn" data-expense-insight="expected" data-insight-key="${esc(row.key)}" ${demoPreview||plan.demo?'disabled':''}>מוכר וצפוי</button></section>`;
}
app.addEventListener('click',event=>{const button=event.target.closest('[data-expense-insight]');if(!button||demoPreview||plan.demo)return;try{mutate(decideExpenseInsight(plan,button.dataset.insightKey,button.dataset.expenseInsight),'הבחירה עודכנה בטיוטה. יש לשמור את התקציב.');}catch(error){notify(error.message);}});

function periodReviewControls(month){
 const state=periodReviewState(plan,month),eligible=month<todayMonth()&&plan.months[month]?.actual&&month!==monthlyPending;
 return `<section class="group"><h3>בדיקת החודש</h3><p class="help">${state==='closed'?'סימנת שסיימת לבדוק את החודש.':state==='reopened'?'המקורות השתנו מאז סיום הבדיקה; יש לבדוק מחדש.':'בדיקת החודש טרם נסגרה.'} הסימון הוא אישור שלך לבדיקה, ולא הוכחה שכל הדוחות קיימים. יבוא מאוחר או שינוי במקורות דורשים בדיקה מחדש.</p><button class="btn" type="button" data-period-review="${month}" data-period-close="${state==='closed'?'no':'yes'}" ${!eligible||demoPreview||plan.demo?'disabled':''}>${state==='closed'?'פתיחת הבדיקה מחדש':'סיימתי לבדוק את החודש'}</button><button class="btn" type="button" data-adopt-categories ${demoPreview||plan.demo?'disabled':''}>קיבוע זהויות לקטגוריות הקיימות</button><button class="btn" type="button" data-category-rename>שינוי שם קטגוריה</button><button class="btn" type="button" data-category-manage>ניהול קטגוריות</button><p class="help">קיבוע זהויות מוסיף מזהים לקטגוריות ללא שינוי שמות, שיוכים או סכומים. כל הפעולות נשמרות רק עם התקציב.</p></section>`;
}
app.addEventListener('click',event=>{
 const review=event.target.closest('[data-period-review]');if(review&&!demoPreview&&!plan.demo){try{mutate(setPeriodReviewed(plan,review.dataset.periodReview,review.dataset.periodClose==='yes',todayMonth(),monthlyPending),'מצב הבדיקה עודכן בטיוטה. יש לשמור את התקציב.');}catch(error){notify(error.message);}return;}
 if(event.target.closest('[data-adopt-categories]')&&!demoPreview&&!plan.demo)confirmAction('לקבע זהויות לקטגוריות הקיימות?','ייווצרו מזהים יציבים לשמות הקיימים. אין שינוי בסכומים או בשמות. השינוי יישמר רק עם התקציב.',()=>{try{mutate(adoptExistingCategories(plan),'זהויות הקטגוריות נוספו לטיוטה. יש לשמור את התקציב.');}catch(error){notify(error.message);}});
});

app.addEventListener('click',event=>{
 if(demoPreview||plan.demo)return;
 const reject=event.target.closest('[data-bank-reject-key]');
 if(reject)confirmAction('לסמן שאלה הוצאות שונות?','המועמדות לא תוצג שוב כל עוד נתוני המקורות לא השתנו. הסכומים לא ישתנו, ואפשר לאפס את הדחיות.',()=>{try{mutate(rejectBankDetailMatch(plan,reject.dataset.bankRejectKey,reject.dataset.bankRejectDetail),'הדחייה עודכנה בטיוטה. יש לשמור את התקציב.');}catch(error){notify(error.message);}});
 if(event.target.closest('[data-bank-rejections-reset]'))confirmAction('לאפס את דחיות ההתאמה?','כל המועמדויות יוצגו שוב לבדיקה. התאמות מאושרות לא יבוטלו.',()=>mutate(resetBankDetailRejections(plan),'הדחיות אופסו בטיוטה. יש לשמור את התקציב.'));
});

app.addEventListener('click',event=>{
 const button=event.target.closest('[data-detail-source]');if(!button)return;
 const row=plan.details?.find(row=>row.id===button.dataset.detailSource);if(!row)return;
 const links=(plan.bankDetailLinks??[]).filter(link=>link.detailId===row.id).map(link=>({link,state:bankDetailLinkState(plan,link.bankKey),entry:plan.bankImport?.entries?.find(entry=>entry.key===link.bankKey)}));
 const dialog=document.createElement('dialog');dialog.className='graph-point-dialog';dialog.innerHTML=`<h2>מקור הרשומה</h2><p><bdi dir="auto">${esc(row.name)}</bdi> · ${money(row.amount)}</p><p class="help">תאריך קנייה <bdi dir="ltr">${esc(row.date)}</bdi> · חודש חיוב <bdi dir="ltr">${esc(row.month)}</bdi></p><p class="help">${row.statement?'פירוט דוח כרטיס שיובא; קובץ המקור עצמו אינו נשמר באפליקציה.':row.wallet?'פירוט מתוך אירוע Wallet שנבדק.':'פירוט שנשמר בתקציב; אין כאן הוכחה שקובץ מקור זמין.'}</p>${row.statement?.issuer==='isracard'?`<p class="help">מקור: ישראכרט${row.statement.page?' · עמוד '+row.statement.page:''}. סכום הרשומה הוא החיוב בשקלים.${row.statement.originalCurrency&&row.statement.foreignCents!==undefined?` סכום המקור: <bdi dir="ltr">${esc((row.statement.foreignCents/100).toFixed(2))} ${esc(row.statement.originalCurrency)}</bdi>. לא מתבצעת המרה נוספת.`:''}</p>`:''}<p class="help">מזהה פירוט: <bdi dir="ltr">${esc(row.id)}</bdi></p>${links.map(({state,entry})=>{const batch=plan.bankImport?.batches?.find(batch=>batch.id===entry?.batchId);return `<section class="group"><h3>${state.status==='confirmed'?'תנועת בנק מקושרת באישור':'התאמה ישנה שדורשת בדיקה'}</h3>${entry?`<p><bdi dir="auto">${esc(entry.source?.description??'תנועה ללא תיאור מקור')}</bdi> · ${money(-entry.cents/100)}</p><p class="help">${esc(batch?.file??'שם קובץ אינו זמין')}${entry.source?.line?' · שורת מקור '+entry.source.line:' · שורת מקור אינה זמינה'} · <bdi dir="ltr">${esc(entry.source?.date??'')}</bdi></p>`:'<p class="help">תנועת הבנק אינה זמינה בתקציב.</p>'}</section>`;}).join('')}<button class="btn" data-detail-source-close>סגירה</button>`;
 const close=()=>{dialog.close();dialog.remove();button.isConnected&&button.focus();};dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.querySelector('[data-detail-source-close]').onclick=close;document.body.append(dialog);dialog.showModal();
});

app.addEventListener('click',event=>{if(!event.target.closest('[data-merchant-reset]')||demoPreview||plan.demo)return;confirmAction('לאפס את כינויי בתי העסק?','התצוגות יחזרו לשמות המקוריים. נתוני המקור והסכומים אינם משתנים. החלטות חיובים חוזרים עשויות לדרוש אישור מחדש.',()=>mutate(resetMerchantRegistry(plan),'הכינויים אופסו בטיוטה. יש לשמור את התקציב.'));});

app.addEventListener('click',event=>{
 if(!event.target.closest('[data-category-rename]')||demoPreview||plan.demo)return;
 if(!guardDetailNavigation())return;
 const dialog=document.createElement('dialog');dialog.className='graph-point-dialog';dialog.innerHTML=`<h2>שינוי שם קטגוריה</h2><p class="help">המזהה והסכומים נשמרים. השמות המקוריים נשארים ברשומות המקור כראיה; הניתוח ישתמש בשם החדש. קטגוריות־משנה יקבלו את התחילית החדשה. אין העברה בין קטגוריות־אב או מיזוג אוטומטי.</p><form><label class="field">קטגוריה<select name="old">${knownCategories().map(label=>`<option>${esc(label)}</option>`).join('')}</select></label><label class="field">שם חדש מלא<input name="new" maxlength="60" required></label><p role="status" data-category-error></p><button class="btn primary">בדיקה ואישור</button><button class="btn" type="button" data-category-close>ביטול</button></form>`;
 const close=()=>{annotationEditorOpen=false;dialog.close();dialog.remove();};dialog.querySelector('[data-category-close]').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
 dialog.querySelector('form').onsubmit=event=>{event.preventDefault();try{const old=dialog.querySelector('[name=old]').value,name=dialog.querySelector('[name=new]').value,next=renameRegisteredCategory(plan,old,name);close();confirmAction('לאשר שינוי שם?',old+' ← '+name+'. הסכומים לא משתנים; השינוי יישמר עם התקציב.',()=>mutate(next,'שם הקטגוריה עודכן בטיוטה. יש לשמור את התקציב.'));}catch(error){dialog.querySelector('[data-category-error]').textContent=error.message;}};
 annotationEditorOpen=true;document.body.append(dialog);dialog.showModal();
});

function bankReconciliationView(month){
 return cashAccountList(plan).map(account=>{const result=reconcileBankMonth(plan,month,account.id,todayMonth());return `<section class="group"><h3>התאמת יתרות · <bdi dir="auto">${esc(account.label)}</bdi></h3>${result.status==='insufficient'?`<p class="help">${esc(result.reason)}</p>`:`<p class="help">פתיחה ${money(result.openingCents/100)} + תנועות נטו ${money(result.movementCents/100,true)} = סגירה מחושבת ${money(result.expectedClosingCents/100)}. יתרת סגירה בדוח ${money(result.closingCents/100)}.</p><p class="help">${result.status==='matched'?'יתרות הקצה תואמות לתנועות שנקלטו.':'נמצא פער של '+currency(result.differenceCents/100)+'. יש לבדוק תנועות חסרות או כפולות בדוח המקורי.'} כל תנועות הבנק נכללות בהתאמה, גם העברות וסילוק כרטיס; זה אינו סך הוצאות.</p>`}</section>`;}).join('');
}

function merchantChangeView(month){
 const result=merchantExpenseChange(plan,{month,asOf:todayMonth(),excludeMonth:monthlyPending});if(!result.available)return '';
 return `<details class="group"><summary>מה השתנה לפי בית עסק?</summary><p class="help">פירוט שנפרע וכלול בסך החודשי, לפי חודש החיוב. שמות מאוחדים רק לפי הכינויים שאישרת. השארית כוללת הוצאות ללא פירוט או התאמה.</p>${result.parts.filter(row=>row.differenceCents!==0).map(row=>`<div class="coverage-source"><button class="btn" type="button" data-merchant-explore="${esc(row.name)}" data-merchant-month="${month}"><bdi dir="auto">${esc(row.name)}</bdi></button>${money(row.differenceCents/100,true)}</div>`).join('')}<p>ללא פירוט או התאמה: ${money(result.remainderCents/100,true)}</p><p>שינוי כולל: ${money(result.changeCents/100,true)}</p></details>`;
}
app.addEventListener('click',event=>{const button=event.target.closest('[data-merchant-explore]');if(!button)return;exploreUI={count:1,end:button.dataset.merchantMonth,category:'',method:'',query:button.dataset.merchantExplore};exploreShown=30;reportView='explore';render();});
